\label{a13}
	Let $\lambda$ be an uncountable regular cardinals.
\begin{enumerate}	
	\item
	 If $\mathbb{G}$ is an abelian group of cardinality $\lambda$ and $\langle
	\mathbb{G}_\alpha:\alpha < \lambda\rangle$ is a filtration of $\mathbb{G}$, then
	\[
	\Gamma(\mathbb{G},\bar{\mathbb{G}}) = \{\delta < \lambda:\mathbb{G}/\mathbb{G}_\delta \text{ is not
	} \lambda\text{-free}\}.
	\]
	\item Let	
$$\Gamma(\mathbb{G}) = \Gamma(\mathbb{G},\bar{\mathbb{G}})/{\mathscr D}_\lambda$$
 for some (and hence every)
	filtration $\bar{\mathbb{G}}$ of $\mathbb{G}.$
\end{enumerate}

Suppose we have the following data of abelian groups and homomorphisms:
	$$
	\begin{CD}
	\mathbb{A}\\
	@AAA  \\
	\mathbb{B} @>>> \mathbb{C}, \\
	\end{CD}
	$$
	We denote the corresponding pushout by
	$\mathbb{A}\oplus_{\mathbb{B}} \mathbb{C}$.

\label{dec}
 If $\diamondsuit_\lambda(S)$  holds, then there is a decomposition $S =\bigcup_{\beta <\lambda }S_{\beta}$
such that $\diamondsuit_\lambda(S_{\beta})$ holds for all $\beta <\lambda$.

\label{hchi}
Let $\chi$ be   be infinite cardinal. By ${\mathscr H}(\chi)$ we mean the collection of sets of hereditary cardinality
less than $\chi$.

Let ${\mathbb P}$ be a forcing notion and $\kappa$ be a regular cardinal.	\begin{enumerate}\item[(a)]  ${\mathbb P}$ is called
		$\kappa$-distributive if the intersection of less than $\kappa$-many dense open subsets of ${\mathbb P}$ is dense, or equivalently, forcing with
		${\mathbb P}$ does not add any new sequences of ordinals of length less than $\kappa.$
		\item[(b)] ${\mathbb P}$ is called $\kappa$-strategically closed if for every $\alpha < \kappa$,  player II has a winning strategy in the following game:
		\begin{itemize}
			\item[$\Game_{{\mathbb P}}(\alpha)$]: the game has length $\alpha$ in which the players I and II take turns to play conditions from ${\mathbb P}$ for $\alpha$-many moves, with player I playing at odd stages and player II at even stages (including all limit stages). II must play $1_{{\mathbb P}}$ at move zero. Let $p_\beta$ b the condition played at move $\beta$; the player who played $p_\beta$ loses immediately unless $p_\beta \geq p_\gamma$ for all $\gamma < \beta.$
			If neither player loses at any stage $\beta < \alpha,$ then player II wins.
		\end{itemize}

		\item[(c)]${\mathbb P}$ is called $\kappa$-c.c. if
		any antichain $A \subseteq {\mathbb P}$ has size less than $\kappa.$	\end{enumerate}

\label{pstarpreservescardinals}
	Adopt the above notation. Then	${\mathbb P}_*$ is $\lambda$-distributive and $\lambda^+$-c.c. In particular, forcing with ${\mathbb P}_*$ does not add any new sequences of ordinals
	of size less than $\lambda$ and it preserves all cardinals.

\label{nosplitifincompatible}
	Suppose $s_*, t_* \in S$ and $(s_*, t_*) \notin R$. Then in $V[\mathbf G_*]$ the exact sequence
	$\mathbf x_{s_*,t_*}$ does not split. In particular, ${\rm Ext}(\mathbb{G}_{s_*}, \mathbb{G}_{t_*}) \neq 0.$

\label{buildingblockforcing}
The forcing notion ${\mathbb Q}^W_{s, t, \mathbf{x}}$ consists of partial functions $q:\mathbb{G}_{t} \dashrightarrow \mathbb{H}$ with domain ${\rm dom}(q)$
such that:
\begin{enumerate}
\item ${\rm dom}(q)= \mathbb{G}_{s, \gamma}$, where $\gamma \notin E$,

\item $g \circ q = {\rm id}_{{\rm dom}(q)}$.
\end{enumerate}
${\mathbb Q}^W_{s, t, \mathbf{x}}$ is ordered by inclusion.

\label{qwforcingproerties}
The forcing notion ${\mathbb Q}^W_{s, t, \mathbf{x}}$ is $\lambda$-closed, $\lambda^+$-c.c., and forcing with it adds a function
$h: \mathbb{G}_t \to \mathbb{H}$ such that $g \circ h={\rm id}_{\mathbb{G}_t}$.

\label{snotRtcase}
Suppose $(s, t) \in (S \times S)\setminus R$. Then the exact sequence
$$
\begin{CD}
\mathbf x_{s,t} :=0@>>> \mathbb{G}_{s} @>f_{s,t}>>\mathbb{H}_{s,t} @>g_{s, t}>> \mathbb{G}_{t} @>>> 0
\end{CD}
$$
does not split in  $V[\mathbf G_* \ast \mathbf G]$.
